<style>
/* 2. CSS: The Paint */

/* Center the card on the screen and paint the background sand-colored */
.preview-container {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background-color: #faf6ee; /* Neo-Brutalist sand color */
